def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    delta = {}
    for start, end in meetings:
        if start == end:
            continue
        delta[start] = delta.get(start, 0) + 1
        delta[end] = delta.get(end, 0) - 1

    total = 0
    active = 0
    times = sorted(delta)
    for i, t in enumerate(times):
        active += delta[t]
        if i + 1 < len(times) and active >= k:
            total += times[i + 1] - t
    return total
